return ['domain'=>'zinn-campaigns','plural-forms'=>'nplurals=3; plural=(n%10==1 && n%100!=11 ? 0 : n%10>=2 && n%10<=4 && (n%100<10 || n%100>=20) ? 1 : 2);','language'=>'hr','project-id-version'=>'zinn-campaigns','pot-creation-date'=>'2026-11-13T22:50:58+00:00','po-revision-date'=>'2026-11-13T22:50:58+00:00','x-generator'=>'scripts/wp-i18n-translate.py','messages'=>['Zinn® Campaigns – Email & SMS Marketing for WooCommerce & More'=>'Zinn® Campaigns – Email & SMS Marketing for WooCommerce & More','https://zinndigital.com/wordpress-plugins/zinn-campaigns'=>'https://zinndigital.com/wordpress-plugins/zinn-campaigns','Connect your WordPress site or WooCommerce store to Zinn® Campaigns in one click and grow your list with double opt-in sign-up forms. Email, SMS and WhatsApp campaigns are sent from your Zinn® Campaigns account.'=>'Povežite svoje WordPress web-mjesto ili WooCommerce trgovinu sa Zinn® Campaigns jednim klikom i proširite svoj popis pomoću obrazaca za prijavu s dvostrukom potvrdom. E-mail, SMS i WhatsApp kampanje šalju se s vašeg Zinn® Campaigns računa.','Neil Lock — CEO, Zinn Digital® Ltd'=>'Neil Lock — CEO, Zinn Digital® Ltd','https://zinndigital.com'=>'https://zinndigital.com','Zinn® Campaigns'=>'Zinn® Campaigns','You are not allowed to manage Zinn® Campaigns on this site.'=>'Nemate dopuštenje za upravljanje Zinn® Campaigns na ovom web-mjestu.','This site is connected to Zinn® Campaigns.'=>'Ova web-stranica povezana je sa Zinn® Campaigns.','This site is disconnected. Sign-up forms stop sending new sign-ups to Zinn® Campaigns.'=>'Ovo web-mjesto je odspojeno. Obrasci za prijavu prestaju slati nove prijave u Zinn® Campaigns.','That connection took too long or was started in another browser. Press Connect again.'=>'To povezivanje je trajalo predugo ili je pokrenuto u drugom pregledniku. Pritisnite ponovno Poveži.','Zinn® did not accept the connection. Press Connect again; if it keeps failing, contact Zinn® support.'=>'Zinn® nije prihvatio vezu. Pritisnite ponovno Poveži; ako se problem nastavi, obratite se Zinn® podršci.','Your site could not reach Zinn®. Check that your host allows outgoing connections, then press Connect again.'=>'Vaša web-lokacija nije se mogla povezati sa Zinn®. Provjerite dopušta li vaš poslužitelj odlazne veze, a zatim pritisnite „Poveži ponovno”.','The %s add-on'=>'Dodatak %s','You get Pro free with any paid Zinn® Campaigns plan: there is no separate licence to buy. Pro is a separate add-on plugin you download from your Zinn® dashboard.'=>'Dobivate Pro besplatno uz bilo koji plaćeni Zinn® Campaigns plan: nema zasebne licence za kupnju. Pro je zaseban dodatak (plugin) koji preuzimate sa svoje Zinn® nadzorne ploče.','Included: your account has a paid Zinn® Campaigns plan.'=>'Uključeno: vaš račun ima plaćeni Zinn® Campaigns plan.','Free trial until %s. Pick any paid Zinn® Campaigns plan to keep Pro after that.'=>'Besplatno probno razdoblje do %s. Odaberite bilo koji plaćeni Zinn® Campaigns paket kako biste zadržali Pro nakon toga.','Not included right now: the free trial has ended or the plan is not paid. Your Pro settings are kept and come back the moment a paid plan is live.'=>'Trenutačno nije uključeno: besplatno probno razdoblje je završilo ili paket nije plaćen. Vaše Pro postavke su sačuvane i vraćaju se onog trenutka kada plaćeni paket postane aktivan.','Connect this site to see what your plan includes.'=>'Povežite ovo web-mjesto kako biste vidjeli što vaš paket uključuje.','Download the Pro add-on'=>'Preuzmite dodatak Pro','See Zinn® Campaigns plans'=>'Pogledajte pakete za Zinn® Campaigns','Sign-up forms'=>'Obrasci za registraciju','Add the "Zinn® Campaigns sign-up form" block to any page or post, or paste a shortcode below. Every sign-up gets a confirmation e-mail first (double opt-in), and only people who confirm join your list.'=>'Dodajte blok „Obrazac za prijavu za Zinn® Campaigns” na bilo koju stranicu ili objavu ili zalijepite kratki kod u nastavku. Svaka prijava najprije prima e-poruku s potvrdom (dvostruka privola), a na Vaš se popis dodaju samo osobe koje potvrde prijavu.','Your account has no sign-up forms yet. Create one in your Zinn® dashboard under Campaigns, Forms, then press Refresh.'=>'Vaš račun još nema obrasce za prijavu. Izradite jedan na svojoj Zinn® nadzornoj ploči pod Kampanje, Obrasci, a zatim pritisnite Osvježi.','Form'=>'Obrazac','List'=>'Popis','Shortcode'=>'Kratki kôd','Grow your list on this site with double opt-in sign-up forms, and send email, SMS and WhatsApp campaigns from your Zinn® Campaigns account.'=>'Proširite svoj popis na ovom web-mjestu obrascima za prijavu s dvostrukom potvrdom te šaljite e-poštu, SMS i WhatsApp kampanje sa svog Zinn® Campaigns računa.','Connect opens Zinn® in this window. Sign in or create an account, approve this site, and you come straight back here. You never paste a key.'=>'„Poveži” otvara Zinn® u ovom prozoru. Prijavite se ili izradite račun, odobrite ovo web-mjesto i vraćate se izravno ovamo. Nikada ne lijepite ključ.','Connect to Zinn® Campaigns'=>'Povežite se sa Zinn® Campaigns','Connected, but Zinn® could not be reached just now. We will try again shortly.'=>'Povezano, ali se trenutno nije moglo pristupiti poslužitelju Zinn®. Uskoro ćemo pokušati ponovno.','Site'=>'Web-mjesto','Connected'=>'Povezano','Open for your account'=>'Otvoreno za vaš račun','Not open for your account yet. Zinn® will e-mail you when it is.'=>'Još nije dostupno za Vaš račun. Zinn® će Vam poslati e-poruku kada postane dostupno.','Refresh'=>'Osvježi','Disconnect'=>'Prekini vezu','You are not allowed to connect this site.'=>'Nemate dopuštenje za povezivanje ove web-lokacije.','You are not allowed to disconnect this site.'=>'Nemate dopuštenje za prekidanje veze ove web-stranice.','Zinn Digital®'=>'Zinn Digital®','Zinn® Campaigns sign-up form'=>'Obrazac za prijavu za Zinn® Campaigns','Choose a form'=>'Odaberite obrazac','A double opt-in sign-up form from your Zinn® Campaigns account.'=>'Obrazac za prijavu s dvostrukom potvrdom s vašeg Zinn® Campaigns računa.','Sign-up form'=>'Obrazac za registraciju','Zinn® Campaigns: connect this site and choose one of your forms to show a sign-up form here.'=>'Zinn® Campaigns: povežite ovo web-mjesto i odaberite jedan od svojih obrazaca kako biste ovdje prikazali obrazac za prijavu.','Sign up'=>'Registrirajte se','Thank you. Check your inbox and click the link in our e-mail to confirm.'=>'Hvala vam. Provjerite svoju pristiglu poštu i kliknite na poveznicu u našoj e-pošti kako biste potvrdili.','Leave this empty'=>'Ostavite ovo prazno','E-mail address'=>'Adresa e-pošte','%s — guides and services'=>'%s — vodiči i usluge','User guides'=>'Korisnički priručnici','Read the %s user guide'=>'Pročitajte korisnički priručnik za %s','Hide this'=>'Sakrij ovo','Zinn® Pro Membership: every Pro plugin, one licence'=>'Zinn® Pro članstvo: svaki Pro priključak, jedna licenca','The Pro versions of Page Builder Sandwich, Tranzly, Zinn® SEO, Zinn® Cache and Zinn® Backups, and every Pro plugin we release next, from %s a year. A second membership adds Zinn® Chat Pro.'=>'Pro verzije za Page Builder Sandwich, Tranzly, Zinn® SEO, Zinn® Cache i Zinn® Backups te svaki sljedeći Pro priključak koji objavimo, već od %s godišnje. Drugo članstvo dodaje Zinn® Chat Pro.','Zinn® hosting for WordPress'=>'Zinn® hosting za WordPress','LiteSpeed, daily backups, free migration and a control panel built for people who run more than one site.'=>'LiteSpeed, svakodnevne sigurnosne kopije, besplatna migracija i upravljačka ploča stvorena za ljude koji vode više od jedne web-stranice.','The Zinn® marketplace'=>'Trgovina Zinn®','Buy and sell established sites, domains and link placements, with the money held safely until both sides are happy.'=>'Kupujte i prodajte etablirane web-stranice, domene i plasmane poveznica, uz sigurno čuvanje novca dok obje strane ne budu zadovoljne.','Zinn Hub® — hire people who do this for a living'=>'Zinn Hub® — zaposlite ljude kojima je ovo struka','Our global freelance marketplace: browse over 10,000 ready-made services from writers, designers, developers and SEOs, or post a project and let them bid.'=>'Naše globalno tržište slobodnih profesionalaca: pregledajte više od 10.000 gotovih usluga pisaca, dizajnera, programera i SEO stručnjaka ili objavite projekt i omogućite im slanje ponuda.','Email me offers and reminders, including about items left in my cart. I can unsubscribe at any time.'=>'Šaljite mi ponude i podsjetnike e-poštom, uključujući i o stavkama preostalima u mojoj košarici. Mogu se odjaviti u bilo kojem trenutku.','See the Zinn Digital® release notes.'=>'Pogledajte bilješke o izdanju za Zinn Digital®.','The Zinn® update service did not issue a download link for this update. Check that this site can reach the Zinn® platform, then try again.'=>'Usluga ažuriranja Zinn® nije pružila poveznicu za preuzimanje ovog ažuriranja. Provjerite može li ova web-stranica pristupiti platformi Zinn®, a zatim pokušajte ponovno.','The update could not be downloaded from the Zinn® update service (%s). Try again in a few minutes.'=>'Ažuriranje se nije moglo preuzeti s usluge ažuriranja za Zinn® (%s). Pokušajte ponovo za nekoliko minuta.','The downloaded update failed its integrity check and was not installed.'=>'Preuzeto ažuriranje nije prošlo provjeru cjelovitosti i nije instalirano.']];